from PIL import Image
import numpy as np
base='/Users/apple/Desktop/microsoft/research_space/hackathon-submission/artifacts/inputs/test_case_5/images/'
im=np.array(Image.open(base+'view_2_left.png').convert('RGB')).astype(float)
g=im.mean(axis=2)
for x in [300,450,600]:
    col=g[:,x]
    print('x=',x)
    # print local minima / strong gradients
    d=np.abs(np.diff(col))
    idx=[y for y in range(1,len(col)-1) if d[y]>6]
    # group
    groups=[]
    for y in idx:
        if groups and y-groups[-1][-1]<=2: groups[-1].append(y)
        else: groups.append([y])
    for gp in groups:
        y=int(np.mean(gp)); print('  y=%d val=%.0f grad=%.0f  Z=%.2f'%(y,col[y],d[y],(1004-y)/5.966))
"", "description": "Scan vertical intensity profile in left view"}

